<?php
/** Proof — attachments and notes (spec "Proof", 5): a PDF stored and served inline with nosniff, the limit, an .exe, delete as Carl, Bea → 403, the agent's note chip, the timeline, an unknown type, an invisible record. */
require __DIR__ . '/lib.php';
$owner = as_member(1); $bea = as_member(27); $carl = as_member(28); $vera = as_member(26);
ensure_year($owner);
[$c, $b, $id] = draft($bea, '2026-06-01', [['account' => '6100', 'debit' => '259.80', 'description' => 'SMOKE hosting'], ['account' => '1010', 'credit' => '259.80']], 'SMOKE with attachments');
echo "1. A PDF\n";
$since = last_activity_id();
[$c, $b] = act_upload($bea, '/attachments/save.php', ['record_type' => 'journal_entry', 'record_id' => $id], ['file' => [tmp_pdf('hosting-april.pdf'), 'hosting-april.pdf']]);
$aid = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $aid > 0 && ($b['url'] ?? '') === '/attachments/get.php?id=' . $aid && str_ends_with((string) $b['location'], '#attachment-chip-' . $aid), 'attachment_add: 200, record_id, the url, location the chip');
$row = q('SELECT filename, mime_type, byte_size, storage_path FROM attachments WHERE id = :a', ['a' => $aid])[0];
$root = dirname(__DIR__, 3) . '/storage/attachments';
ok($row['mime_type'] === 'application/pdf' && str_starts_with($row['storage_path'], 'journal_entry/' . $id . '/' . $aid . '-') && is_file($root . '/' . $row['storage_path']), 'stored under storage/attachments/journal_entry/<id>/ with the mime from finfo');
$log = activity('attachment.add', $since);
ok(count($log) === 1 && (int) $log[0]['journal_entry_id'] === $id && str_contains((string) $log[0]['after'], '"filename": "hosting-april.pdf"') && str_contains((string) $log[0]['after'], '"mime_type": "application/pdf"'), 'attachment.add logged with the file and the entry key');
$r = req('GET', '/attachments/get.php?id=' . $aid, ['jar' => $vera]);
ok($r['code'] === 200 && preg_match('/^Content-Type: application\/pdf/mi', $r['headers']) === 1 && preg_match('/^X-Content-Type-Options: nosniff/mi', $r['headers']) === 1 && preg_match('/^Content-Disposition: inline/mi', $r['headers']) === 1 && str_starts_with($r['body'], '%PDF'), 'served inline with nosniff to a Viewer (who sees the entry)');
ok(req('GET', '/attachments/get.php?id=' . $aid)['code'] === 302, 'without a session: the launcher');
ok(req('GET', '/attachments/get.php?id=424242', ['jar' => $vera])['code'] === 404, 'an unknown id: 404');
$big = tmp_pdf('big.pdf', (int) need('ATTACHMENT_MAX_BYTES') + 1);
[$c, $b] = act_upload($bea, '/attachments/save.php', ['record_type' => 'journal_entry', 'record_id' => $id], ['file' => [$big, 'big.pdf']]);
ok($c === 422 && str_contains(fields($b)['file'] ?? '', 'larger than'), 'the limit + 1 byte: 422 "larger than …"');
$exe = sys_get_temp_dir() . '/SMOKE.exe'; file_put_contents($exe, "MZ\x90\x00" . str_repeat("\x00", 200));
[$c, $b] = act_upload($bea, '/attachments/save.php', ['record_type' => 'journal_entry', 'record_id' => $id], ['file' => [$exe, 'tool.exe']]);
ok($c === 422 && str_contains(fields($b)['file'] ?? '', 'not accepted'), 'an .exe: 422 "not accepted"');
[$c, $b] = act_upload($vera, '/attachments/save.php', ['record_type' => 'journal_entry', 'record_id' => $id], ['file' => [tmp_pdf('v.pdf'), 'v.pdf']]);
ok($c === 403 && msg($b) === 'You may not attach documents.', 'a Viewer (no attachments.write): 403');
[$c, $b] = act_upload($bea, '/attachments/save.php', ['record_type' => 'magic', 'record_id' => 1], ['file' => [tmp_pdf('m.pdf'), 'm.pdf']]);
ok($c === 422 && str_contains(msg($b), 'No record of that kind'), 'an unknown record type: 422');
[$c, $b] = act_upload($bea, '/attachments/save.php', ['record_type' => 'customer', 'record_id' => 424242], ['file' => [tmp_pdf('c.pdf'), 'c.pdf']]);
ok($c === 404 && msg($b) === 'Customer not found.', 'a customer id nobody sees: 404 "Customer not found."');
[$c, $b] = act_upload($bea, '/attachments/save.php', ['record_type' => 'journal_entry', 'record_id' => $id], []);
ok($c === 422 && str_contains(fields($b)['file'] ?? '', 'Choose a file'), 'no file: 422');
echo "2. Delete\n";
[$c, $b] = act($bea, '/attachments/delete.php', ['attachment' => $aid]);
ok($c === 403 && msg($b) === 'You may not reverse, void or write off.' && is_file($root . '/' . $row['storage_path']), 'Bea deleting (journal.override): 403, the file stays');
$since = last_activity_id();
[$c, $b] = act($carl, '/attachments/delete.php', ['attachment' => $aid]);
clearstatcache(true, $root . '/' . $row['storage_path']);   // PHP caches stat() per process: the earlier is_file() would answer again
ok($c === 200 && !is_file($root . '/' . $row['storage_path']) && one('SELECT 1 FROM attachments WHERE id = :a', ['a' => $aid]) === false && count(activity('attachment.delete', $since)) === 1, 'Carl deletes it: the row and the file are gone; attachment.delete logged' . ($c === 200 ? '' : " ($c " . msg($b) . ')'));
ok(req('GET', '/attachments/get.php?id=' . $aid, ['jar' => $vera])['code'] === 404, 'and it serves 404');
echo "3. Notes and the timeline\n";
$since = last_activity_id();
[$c, $b] = act($vera, '/notes/save.php', ['record_type' => 'journal_entry', 'record_id' => $id, 'body' => 'SMOKE a note from Vera']);
$nid = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $nid > 0 && str_ends_with((string) $b['location'], '#note-' . $nid) && str_contains((string) activity('note.add', $since)[0]['after'], 'SMOKE a note from Vera'), 'note_add by a Viewer (documents.view): 200, note.add logged with the excerpt');
[$c, $b] = act_token('/notes/save.php', ['record_type' => 'journal_entry', 'record_id' => $id, 'body' => 'SMOKE the agent notes'], ['X-Action-Token: ' . person_token(40)]);
ok($c === 200, 'a note under the Bookkeeper agent\'s token');
$body = page($bea, '/journal/' . $id)['body'];
ok(str_contains($body, 'SMOKE the agent notes') && preg_match('/SMOKE the agent notes.*?|.*?agent/s', $body) === 1 && str_contains($body, 'id="entry-notes"') && str_contains($body, 'badge bg-soft-info text-info">agent</span> ·'), 'the notes panel shows the agent\'s note with the chip');
[$c, $b] = act($vera, '/notes/save.php', ['record_type' => 'journal_entry', 'record_id' => $id, 'body' => '   ']);
ok($c === 422 && msg($b) === 'Write the note first.', 'a blank note: 422');
[$c, $b] = act($vera, '/notes/save.php', ['record_type' => 'invoice', 'record_id' => 424242, 'body' => 'x']);
ok($c === 404, 'a note on an invoice nobody sees: 404');
$d = entry_json($bea, $id);
$sentences = array_column($d['timeline'], 'sentence');
ok(count($d['notes']) === 2 && $d['notes'][0]['by']['kind'] === 'agent' && $sentences !== [] && str_contains(implode(' | ', $sentences), 'drafted an entry') && str_contains(implode(' | ', $sentences), 'attached a document hosting-april.pdf') && str_contains(implode(' | ', $sentences), '(agent) added a note'), 'the JSON: two notes (the agent\'s first), the timeline in sentences: ' . $sentences[count($sentences) - 1]);
act($bea, '/journal/post.php', ['entry' => $id]);
$d = entry_json($bea, $id);
$s = implode(' | ', array_column($d['timeline'], 'sentence'));
ok(str_contains($s, 'posted an entry JE-') && str_contains($s, '(259.80 USD) into 2026-06'), 'after the post the timeline says "posted an entry JE-… (259.80 USD) into 2026-06"');
$body = page($bea, '/journal/' . $id)['body'];
ok(str_contains($body, 'id="entry-timeline"') && preg_match('/timeline-row-\d+/', $body) === 1, 'the timeline panel renders');
finish();
